import {fixedUsdPrice} from './stablecoins.mjs';
// Decimal arithmetic: no rounding across the settlement boundary.
export function decimal(value){const m=String(value).match(/^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i);if(!m)throw Error('无效金额');let digits=m[1]+(m[2]||''),scale=(m[2]||'').length-Number(m[3]||0);if(Math.abs(scale)>100)throw Error('精度过大');if(scale<0){digits+='0'.repeat(-scale);scale=0}return {n:BigInt(digits),scale}}
export function valueGroups(groups,prices,settings={},now=Date.now()){
 const threshold=decimal(settings.threshold??'0.1');return groups.map(g=>{const p=fixedUsdPrice(g.chain,g.asset,now)||prices[g.chain+':'+g.asset];const fresh=p&&Number(p.usd)>0&&now-p.at<15*60e3&&p.at<=now+60000;const exactStatus=g.status;if(!fresh)return {...g,exactStatus,priced:false};const price=decimal(p.usd),net=BigInt(g.due)-BigInt(g.paid),abs=net<0n?-net:net;const withinTolerance=settings.enabled!==false&&abs>0n&&abs*price.n*10n**BigInt(threshold.scale)<threshold.n*10n**BigInt(g.decimals+price.scale);const usd=raw=>Number(raw)/10**g.decimals*Number(p.usd);return {...g,exactStatus,status:withinTolerance?'settled':g.status,withinTolerance,priced:true,price:p,usdDue:usd(g.due),usdPaid:usd(g.paid),usdRemaining:usd(g.remaining),usdExcess:usd(g.excess),usdDifference:usd(abs)}})
}
export function addressTotals(groups){const totals=new Map;for(const g of groups){const key=(g.chain==='solana'?'sol:':'evm:')+g.trader;const a=totals.get(key)||{due:0,paid:0,remaining:0,excess:0,missing:0};if(!g.priced)a.missing++;else{a.due+=g.usdDue;a.paid+=g.usdPaid;a.remaining+=g.usdRemaining;a.excess+=g.usdExcess}totals.set(key,a)}return totals}
export function filterMinimum(groups,minimum,field='due'){const totals=addressTotals(groups),min=Number(minimum)||0;return groups.filter(g=>{const a=totals.get((g.chain==='solana'?'sol:':'evm:')+g.trader);return !min||a.missing>0||a[field]>=min})}
